+/*
+  고른 섹터에만 나타나는 비중 묶음이다. 고르는 label 밖에 있어 여기를 만져도 섹터가 풀리지 않는다.
+  점선으로 카드 안에서 층이 나뉘는 것을 보인다.
+*/
+.item [data-slot='weight'] {
+  display: flex;
+  flex-wrap: wrap;
+  align-items: center;
+  gap: 8px 12px;
+  margin: 0 16px;
+  padding: 12px 0 14px;
+  border-top: 1px dashed var(--thorp-line);
+}
+
+.item [data-slot='weight-label'] {
+  color: var(--thorp-copy);
+  font-size: 0.78rem;
+  white-space: nowrap;
+}
+
+/* 슬라이더와 숫자 칸이 좁은 화면에서 서로를 밀어내지 않게 한 묶음으로 두고 함께 줄인다. */
+.item [data-slot='weight-controls'] {
+  display: flex;
+  flex: 1 1 12rem;
+  align-items: center;
+  gap: 10px;
+  min-width: 0;
+}
+
+.item [data-slot='weight-slider'] {
+  flex: 1 1 6rem;
+  min-width: 0;
+  accent-color: var(--thorp-accent);
+  cursor: pointer;
+}
+
+.item [data-slot='weight-number'] {
+  display: inline-flex;
+  align-items: center;
+  gap: 4px;
+}
+
+.item [data-slot='weight-field'] {
+  width: 5.5rem;
+  padding: 6px 10px;
+  border: 1px solid var(--thorp-line);
+  border-radius: 8px;
+  background: var(--thorp-surface);
+  color: inherit;
+  font: inherit;
+  font-size: 0.88rem;
+}
+
+.item [data-slot='weight-unit'] {
+  color: var(--thorp-copy);
+  font-size: 0.82rem;
+}
+
+/* 받지 않은 입력을 알리는 한 문장이다. 그 자리에 둔다. */
+.item [data-slot='weight-error'] {
+  flex-basis: 100%;
+  color: var(--thorp-copy);
+  font-size: 0.78rem;
+  line-height: 1.5;
+}
+
+/* 합계와 남은 비중이 놓이는 자리다. 별도 알림 영역으로 빼지 않는다. */
+.total {
+  display: grid;
+  grid-template-columns: 1fr auto;
+  align-items: center;
+  gap: 10px 14px;
+  padding: 12px 16px;
+  border: 1px solid var(--thorp-line);
+  border-radius: 12px;
+  background: var(--thorp-surface);
+}
+
+.total p {
+  grid-column: 1;
+  grid-row: 1;
+  margin: 0;
+  font-size: 0.9rem;
+  line-height: 1.6;
+}
+
+/* 100% 가운데 얼마가 찼고 얼마가 넘쳤는지를 눈으로 보인다. 문장이 읽어 주는 값과 같은 값이다. */
+.total [data-slot='weight-total-bar'] {
+  display: flex;
+  grid-column: 1 / -1;
+  grid-row: 2;
+  width: 100%;
+  height: 8px;
+  overflow: hidden;
+  border-radius: 999px;
+  background: var(--thorp-surface-muted);
+}
+
+.total [data-slot='weight-total-fill'],
+.total [data-slot='weight-total-over'] {
+  flex: none;
+}
+
+.total [data-slot='weight-total-fill'] {
+  background: var(--thorp-accent);
+  transition: width 0.15s ease;
+}
+
+.total [data-slot='weight-total-bar'][data-state='short'] [data-slot='weight-total-fill'] {
+  background: var(--thorp-warning);
+}
+
+.total [data-slot='weight-total-bar'][data-state='over'] [data-slot='weight-total-fill'] {
+  background: var(--thorp-negative);
+}
+
+/* 100%를 넘은 몫이다. 채워진 몫과 다른 색으로 두어 얼마나 넘쳤는지 바로 보이게 한다. */
+.total [data-slot='weight-total-over'] {
+  background: var(--thorp-negative);
+  opacity: 0.55;
+}
+
+.total button {
+  grid-column: 2;
+  grid-row: 1;
+  padding: 7px 14px;
+  border: 1px solid var(--thorp-line);
+  border-radius: 999px;
+  background: transparent;
+  color: inherit;
+  font: inherit;
+  font-size: 0.84rem;
+  cursor: pointer;
+}
+
+.total button:hover {
+  border-color: currentColor;
+}
+
+/* 두 개 이상 골라야 한다는 안내다. 하나만 골랐을 때만 나타난다. */
+.constraintNotice {
+  margin: 0;
+  color: var(--thorp-copy);
+  font-size: 0.86rem;
+  line-height: 1.6;
+}
+
 .attribution {
   margin: 4px 0 0;
   color: var(--thorp-copy);
